const userIDsByUUID = `-- name: UserIDsByUUID :many
SELECT uuid, id
FROM users
WHERE uuid IN (/*SLICE:uuids*/?)
`

type UserIDsByUUIDRow struct {
	Uuid string
	ID   uint32
}

func (q *Queries) UserIDsByUUID(ctx context.Context, uuids []string) ([]UserIDsByUUIDRow, error) {
	query := userIDsByUUID
	var queryParams []interface{}
	if len(uuids) > 0 {
		for _, v := range uuids {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:uuids*/?", strings.Repeat(",?", len(uuids))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:uuids*/?", "NULL", 1)
	}
	rows, err := q.db.QueryContext(ctx, query, queryParams...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []UserIDsByUUIDRow
	for rows.Next() {
		var i UserIDsByUUIDRow
		if err := rows.Scan(&i.Uuid, &i.ID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

